-- Pearls/Books.lua: library books (#72). WoW Forever's library books on the
-- world map and the minimap, and a toast when you come near one you still
-- need. The toast and the panel are Pearls/BooksFrame.lua.
--
-- The data is Data/Books.lua (generated by Tools/gen_books.py: the client's
-- 40 books, Wowhead Forever's spots accepted book by book, a few by hand).
-- Pins go through the vendored HereBeDragons-2.0 + Pins as the map landmarks'
-- do: tooltip only, clicks pass through. Our data keeps the client tables'
-- world order (x north, y west); HereBeDragons' world is (west, north), so
-- every world call passes (y, x).
--
-- A book's state, read fresh, every read plain or "unknown":
--   hidden   absent from Forever, or the other faction's (a faction read plain)
--   done     its quest plainly completed (this character)
--   have     carried or banked (GetItemCount with the bank, or this
--            character's remembered bank list: GlassPearlsCharDB.books.bank)
--   need     the quest plainly not completed, the count plainly 0, not banked,
--            and the bank established: seen open once on this character
--            (GlassPearlsCharDB.books.bankSeen), unless BANK_COUNT_UNOPENED
--   unknown  anything else (an unconfirmed book is never "need")
-- A remembered bank entry goes when a bank visit reads the book gone, or when
-- the book reads plainly carried (unique: carried means not in the bank). A
-- book whose counts can't be read during a bank visit is unresolved
-- (books.unsure): unknown, whatever was remembered, until a later visit reads
-- it or it reads plainly carried.
-- The map shows need and unknown; the toast only need.
--
-- Nearby: a 1 s ticker while on. HereBeDragons' player position inside one
-- pcall, every return plain; distance only to spots on the same continent
-- (its GetWorldDistance ignores the instance). A latch per book: alerted once
-- on coming within ENTER yards of any of its spots, re-armed only by a plain
-- reading LEAVE yards from all of them (a book with no spot on this continent
-- keeps its latch: #93). Quiet in an instance, dead or on a taxi.
--
-- The compass (#93, setting `compass`, Pearls/BooksCompass.lua draws it): the
-- toast's book becomes the target (in memory). Ended by arriving within NEAR
-- yards (backing away doesn't bring it back), its LEAVE re-arm, its state
-- proved have / done / hidden, the pearl, `nearby` or `compass` off. Hidden,
-- kept, while unknown, quiet, unreadable, on another continent or in combat:
-- the ticker reconciles it every second, toast or not (Codex, three rounds).

GlassPearls = GlassPearls or {}
local GP = GlassPearls
local API = GP.API
local B = {}
GP.Books = B

B.KEY = "books"
B.ENTER, B.LEAVE = 100, 150
B.NEAR = 10            -- yards: the compass's book reached
B.SHOW_CONTINENT = 2   -- HBD_PINS_WORLDMAP_SHOW_CONTINENT (HereBeDragons-Pins-2.0.lua)
B.SIZE = 14
B.ICON = "Interface\\Icons\\INV_Misc_Book_09"
B.FACTIONS = { Alliance = true, Horde = true }
-- Whether GetItemCount(item, true) counts the bank before it is opened this
-- session. Unmeasured: false until day one shows it does.
B.BANK_COUNT_UNOPENED = false

local events = CreateFrame("Frame")
local frames = { world = {}, mini = {} }   -- pools, one per display
local used = { world = 0, mini = 0 }
local states = {}          -- item -> state, as last refreshed
local latched = {}         -- item -> true once alerted, until LEAVE yards away
local target               -- the compass's book (#93), or nil
local bankOpen = false
local session = 0          -- bumped by Enable and Disable; deferred calls check it
local pending = false
local ticker
B.placed = {}              -- what the last build placed, for the tests and /gpearls

local function setting(name) return GP.Pearls.Setting(B.KEY, name) end
local function data() return GP.BookData end

local function plainNumber(v)
    if API.IsSecret(v) or type(v) ~= "number" or v ~= v or v == math.huge or v == -math.huge then return nil end
    return v
end

local function lib(name)
    local stub = rawget(_G, "LibStub")
    return stub and stub(name, true)
end

--------------------------------------------------------------------------------
-- Reads

-- "Alliance" / "Horde" from the tag (the first return), else nil.
function B.Faction()
    local ok, tag = pcall(UnitFactionGroup, "player")
    if not ok or API.IsSecret(tag) or not B.FACTIONS[tag] then return nil end
    return tag
end

local function completed(quest)
    local QL = rawget(_G, "C_QuestLog")
    if not (QL and QL.IsQuestFlaggedCompleted) then return nil end
    local ok, v = pcall(QL.IsQuestFlaggedCompleted, quest)
    if not ok or API.IsSecret(v) or type(v) ~= "boolean" then return nil end
    return v
end

local function count(item, bank)
    local ok, n = pcall(C_Item.GetItemCount, item, bank)
    if not ok then return nil end
    n = plainNumber(n)
    return n and n >= 0 and n or nil
end

-- GlassPearlsCharDB.books: { bank = { [item] = true }, unsure = { [item] = true }, bankSeen = true }.
local function store(create)
    local c = GP.charDB
    if type(c) ~= "table" then return nil end
    if type(c.books) ~= "table" then
        if not create then return nil end
        c.books = {}
    end
    if type(c.books.bank) ~= "table" or type(c.books.unsure) ~= "table" then
        if not create then return nil end
        c.books.bank = type(c.books.bank) == "table" and c.books.bank or {}
        c.books.unsure = type(c.books.unsure) == "table" and c.books.unsure or {}
    end
    return c.books
end

local function bankEstablished()
    if B.BANK_COUNT_UNOPENED then return true end
    local st = store(false)
    return st ~= nil and st.bankSeen == true
end
B.BankEstablished = bankEstablished

function B.State(book)
    if book.status == "absent" then return "hidden" end
    if book.faction then
        local mine = B.Faction()
        if not mine then return "unknown" end
        if mine ~= book.faction then return "hidden" end
    end
    local done = completed(book.quest)
    if done == true then return "done" end
    local st = store(false)
    local carried = count(book.item, false)
    if carried and carried > 0 then
        if st then st.bank[book.item], st.unsure[book.item] = nil, nil end   -- carried: not in the bank
        return "have"
    end
    if st and st.unsure[book.item] then return "unknown" end
    local n = count(book.item, true)
    if n and n > 0 then return "have" end
    if st and st.bank[book.item] then return "have" end
    if book.status == "unconfirmed" then return "unknown" end
    if done == false and n == 0 and bankEstablished() then return "need" end
    return "unknown"
end

-- While the bank is open: which books are in it (both counts plain).
local function recordBank()
    if not bankOpen then return end
    local st = store(true)
    if not st then return end
    local whole = true
    for _, book in ipairs(data().books) do
        local all, carried = count(book.item, true), count(book.item, false)
        if all and carried then
            st.bank[book.item], st.unsure[book.item] = (all - carried > 0) or nil, nil
        else
            st.unsure[book.item], whole = true, false
        end
    end
    if whole then st.bankSeen = true end
end

-- The player's world position: continent, north, west; nil when unreadable.
function B.Position()
    local HBD = lib("HereBeDragons-2.0")
    if not (HBD and HBD.GetPlayerWorldPosition) then return nil end
    local ok, west, north, continent = pcall(HBD.GetPlayerWorldPosition, HBD)
    if not ok then return nil end
    west, north, continent = plainNumber(west), plainNumber(north), plainNumber(continent)
    if not (west and north and continent) then return nil end
    return continent, north, west
end

-- The nearest spot of a book on this continent: yards and the spot, or nil.
function B.Nearest(book, continent, north, west)
    local best, spot
    for _, s in ipairs(book.spots) do
        if s.c == continent then
            local d = math.sqrt((north - s.x) ^ 2 + (west - s.y) ^ 2)
            if not best or d < best then best, spot = d, s end
        end
    end
    return best, spot
end

local function quiet()
    local ok, inside = pcall(IsInInstance)
    if not ok or API.IsSecret(inside) or inside ~= false then return true end
    local okD, dead = pcall(UnitIsDeadOrGhost, "player")
    if not okD or API.IsSecret(dead) or dead ~= false then return true end
    local okT, taxi = pcall(UnitOnTaxi, "player")
    if not okT or API.IsSecret(taxi) or taxi ~= false then return true end
    return false
end
B.Quiet = quiet

-- Combat: Glass Pearls' noted combat or lockdown, or UnitAffectingCombat plainly
-- true (NodeRadar's read: after a reload in combat the lockdown can read false).
function B.InCombat()
    if API.InCombat() then return true end
    local ok, v = pcall(UnitAffectingCombat, "player")
    return ok and not API.IsSecret(v) and v == true
end

--------------------------------------------------------------------------------
-- The compass's target (#93)

local function ring() return GP.BooksCompass end
local function hideRing() if ring() then ring().Hide() end end
local function compassOn() return B.enabled and setting("nearby") and setting("compass") and true or false end

function B.Target() return target end

local function clearTarget()
    target = nil
    hideRing()
end
-- The ring reached its book (its own frame, the same rule as the ticker's).
function B.Arrive() clearTarget() end

-- The target against its state: false when it can't be shown now (cleared, or kept hidden).
-- (The switches clear it themselves; a toast sets it only with the compass on.)
local function stateAllows()
    if not target then hideRing(); return false end
    local s = states[target.item]
    if s == "have" or s == "done" or s == "hidden" then clearTarget(); return false end
    if s ~= "need" then hideRing(); return false end           -- unknown: kept, hidden
    return true
end

-- With a usable reading (not quiet, the position plain): arrival clears, else
-- shown; the ring's own frame hides it at once in combat or on a failed read.
local function reconcile(continent, north, west)
    if not stateAllows() then return end
    local d, spot = B.Nearest(target, continent, north, west)
    if not d then return hideRing() end                        -- another continent: kept
    if d <= B.NEAR then return clearTarget() end
    ring().Show(target, spot)
end

--------------------------------------------------------------------------------
-- Names and tooltips

function B.Name(book)
    local ok, name = pcall(C_Item.GetItemNameByID, book.item)
    if ok and not API.IsSecret(name) and type(name) == "string" and name ~= "" then return name end
    if C_Item.RequestLoadItemDataByID then pcall(C_Item.RequestLoadItemDataByID, book.item) end
    return "Library book"
end

function B.Icon(book)
    local ok, icon = pcall(C_Item.GetItemIconByID, book.item)
    if ok and not API.IsSecret(icon) and (type(icon) == "number" or type(icon) == "string") then return icon end
    return B.ICON
end

function B.ZoneName(zone)
    local ok, info = pcall(C_Map.GetMapInfo, zone)
    local name = ok and type(info) == "table" and info.name
    if name and not API.IsSecret(name) and type(name) == "string" and name ~= "" then return name end
    return "Map " .. zone
end

function B.Where(spot)
    return ("%s %.1f, %.1f"):format(B.ZoneName(spot.zone), spot.mx, spot.my)
end

function B.TooltipLines(book, spot, state)
    local lines = { { B.Name(book), 1, 0.82, 0 }, { "Library book", 1, 1, 1 }, { B.Where(spot), 0.8, 0.8, 0.8 } }
    local function add(text, r, g, b) lines[#lines + 1] = { text, r or 0.8, g or 0.8, b or 0.8 } end
    if book.entrance then add("Cave entrance: the book is inside", 1, 0.82, 0) end
    if book.note then add(book.note) end
    if #book.spots > 1 then add(("One of %d places for this book"):format(#book.spots)) end
    if book.status == "unconfirmed" then add("Not confirmed in WoW Forever", 1, 0.5, 0.25) end
    if state == "unknown" and book.status ~= "unconfirmed" then
        add(bankEstablished() and "Can't tell whether you have it" or "Open your bank once so it can be checked",
            1, 0.5, 0.25)
    end
    return lines
end

local function onEnter(f)
    if not f.book then return end
    GameTooltip:SetOwner(f, "ANCHOR_RIGHT")
    for i, l in ipairs(B.TooltipLines(f.book, f.spot, states[f.book.item])) do
        if i == 1 then GameTooltip:SetText(l[1], l[2], l[3], l[4]) else GameTooltip:AddLine(l[1], l[2], l[3], l[4], true) end
    end
    GameTooltip:Show()
end
local function onLeave() GameTooltip:Hide() end

--------------------------------------------------------------------------------
-- Pins

local function acquire(display)
    used[display] = used[display] + 1
    local f = frames[display][used[display]]
    if not f then
        f = CreateFrame("Frame", nil, UIParent)
        f.tex = f:CreateTexture(nil, "OVERLAY")
        f.tex:SetAllPoints(f)
        f.tex:SetTexture(B.ICON)
        f.tex:SetTexCoord(0.08, 0.92, 0.08, 0.92)
        f:SetMouseClickEnabled(false)
        f:SetMouseMotionEnabled(true)
        f:SetScript("OnEnter", onEnter)
        f:SetScript("OnLeave", onLeave)
        frames[display][used[display]] = f
    end
    f:SetSize(B.SIZE, B.SIZE)
    -- Hidden, unanchored: HereBeDragons shows and places only what it draws; a
    -- pin on another continent is never touched by it (#95).
    f:Hide()
    f:ClearAllPoints()
    return f
end

local function clear()
    local P = lib("HereBeDragons-Pins-2.0")
    if P then
        P:RemoveAllWorldMapIcons(B)
        P:RemoveAllMinimapIcons(B)
    end
    for display, list in pairs(frames) do
        for i = 1, used[display] do
            list[i]:Hide()
            list[i].book, list[i].spot = nil, nil
        end
        used[display] = 0
    end
    B.placed = {}
end

local function place(P, display, book, spot)
    local f = acquire(display)
    f.book, f.spot = book, spot
    local ok
    if display == "world" then
        ok = P:AddWorldMapIconWorld(B, f, spot.c, spot.y, spot.x, B.SHOW_CONTINENT)
    else
        ok = P:AddMinimapIconWorld(B, f, spot.c, spot.y, spot.x, false)
    end
    B.placed[#B.placed + 1] = { display = display, book = book, spot = spot, ok = ok ~= false }
    if ok == false then API.Fail("pearl books pin", book.item .. " on the " .. display) end
end

function B.Build()
    clear()
    local P, d = lib("HereBeDragons-Pins-2.0"), data()
    if not P or not d then
        API.Fail("pearl books", not P and "HereBeDragons-Pins-2.0 not loaded" or "no data")
        return false
    end
    local worldOn, miniOn = setting("worldmap"), setting("minimap")
    if not (worldOn or miniOn) then return true end
    for _, book in ipairs(d.books) do
        local s = states[book.item]
        if s == "need" or s == "unknown" then
            for _, spot in ipairs(book.spots) do
                if worldOn then place(P, "world", book, spot) end
                if miniOn then place(P, "mini", book, spot) end
            end
        end
    end
    return true
end

--------------------------------------------------------------------------------
-- Refresh

-- Every book's state again; the pins rebuilt only when a state changed (or forced).
function B.Refresh(force)
    if not B.enabled then return end
    recordBank()
    local changed = force
    for _, book in ipairs(data().books) do
        local s = B.State(book)
        if states[book.item] ~= s then changed, states[book.item] = true, s end
    end
    if changed then B.Build() end
    stateAllows()                                              -- shown again by the ticker
end

-- One refresh a frame later, however many events asked.
local function schedule()
    if pending or not B.enabled then return end
    pending = true
    local mine = session
    C_Timer.After(0, function()
        if mine ~= session then return end
        pending = false
        B.Refresh()
    end)
end

events:SetScript("OnEvent", function(_, event, arg)
    API.NoteCombat(event)
    if event == "PLAYER_REGEN_DISABLED" then return hideRing()
    elseif event == "PLAYER_REGEN_ENABLED" then return B.Tick()  -- the compass back at once
    elseif event == "BANKFRAME_OPENED" then bankOpen = true
    elseif event == "BANKFRAME_CLOSED" then
        recordBank()
        bankOpen = false
    elseif event == "UNIT_FACTION" and (API.IsSecret(arg) or arg ~= "player") then return
    end
    schedule()
end)
B.EVENTS = { "PLAYER_ENTERING_WORLD", "QUEST_TURNED_IN", "QUEST_LOG_UPDATE", "BAG_UPDATE_DELAYED",
             "BANKFRAME_OPENED", "BANKFRAME_CLOSED", "PLAYERBANKSLOTS_CHANGED", "UNIT_FACTION",
             "PLAYER_REGEN_DISABLED", "PLAYER_REGEN_ENABLED" }

--------------------------------------------------------------------------------
-- Nearby

-- One second: newly entered books alerted (a chat line each, the nearest on
-- the toast), then the compass reconciled, toast or not. In order: the latches
-- (a re-arm ends that book's compass), the toast's book as the new target, then
-- that target's arrival or show (Codex: an expired one never shows for a tick).
function B.Tick()
    if not (B.enabled and setting("nearby")) or quiet() then return end   -- a shown ring hides itself
    local continent, north, west = B.Position()
    if not continent then return end
    local entered = {}
    for _, book in ipairs(data().books) do
        local d, spot = B.Nearest(book, continent, north, west)
        if d and d >= B.LEAVE then
            latched[book.item] = nil
            if target == book then target = nil end
        elseif d and d <= B.ENTER and not latched[book.item] and states[book.item] == "need" then
            latched[book.item] = true
            entered[#entered + 1] = { book = book, spot = spot, yards = d }
        end
    end
    if #entered > 0 then
        table.sort(entered, function(a, b)
            if a.yards ~= b.yards then return a.yards < b.yards end
            return a.book.item < b.book.item
        end)
        for _, e in ipairs(entered) do
            local near = e.book.entrance and "near its cave entrance"
                or ("about %d yards away"):format(math.floor(e.yards + 0.5))
            API.Print(("Library book nearby: %s, %s (%s)."):format(B.Name(e.book), near, B.Where(e.spot)))
        end
        local first = entered[1]
        if GP.BooksFrame then GP.BooksFrame.Show(B.View(first.book, first.spot, first.yards)) end
        if compassOn() then target = first.book end
    end
    reconcile(continent, north, west)
end

-- What the toast shows.
function B.View(book, spot, yards)
    return { item = book.item, name = B.Name(book), icon = B.Icon(book), where = B.Where(spot),
             distance = book.entrance and "Near the cave entrance: the book is inside"
                 or (yards and ("About %d yards away"):format(math.floor(yards + 0.5)) or nil),
             note = book.note, unconfirmed = book.status == "unconfirmed" }
end

local function startTicker()
    if ticker or not (B.enabled and setting("nearby")) then return end
    ticker = C_Timer.NewTicker(1, B.Tick)
end

local function stopTicker()
    if ticker then ticker:Cancel() end
    ticker = nil
end

--------------------------------------------------------------------------------
-- The command

local function summary()
    local n = { need = 0, have = 0, done = 0, unknown = 0, hidden = 0 }
    for _, book in ipairs(data().books) do
        local s = states[book.item] or B.State(book)
        n[s] = n[s] + 1
    end
    API.Print(("Library books: %d to find, %d carried or banked, %d handed in, %d can't tell."):format(
        n.need, n.have, n.done, n.unknown))
    if not bankEstablished() then API.Print("  Open your bank once so the books in it can be told.") end
    local continent, north, west = B.Position()
    if not continent then return API.Print("  Your position can't be read here.") end
    local best
    for _, book in ipairs(data().books) do
        if states[book.item] == "need" then
            local d, spot = B.Nearest(book, continent, north, west)
            if d and (not best or d < best.d) then best = { d = d, book = book, spot = spot } end
        end
    end
    if best then
        API.Print(("  Nearest to find: %s, about %d yards (%s)."):format(B.Name(best.book),
            math.floor(best.d + 0.5), B.Where(best.spot)))
    else
        API.Print("  None to find on this continent.")
    end
end

local function command(arg)
    if arg and arg:match("^%s*compass%s+reset%s*$") then
        if ring() then ring().ResetPosition() end
        return API.Print("Library books: the compass is back under your character.")
    end
    if not B.enabled then return API.Print("Library books is off: /gpearls books on.") end
    if arg == "test" then
        local book = data().books[1]
        return GP.BooksFrame.Show(B.View(book, book.spots[1], 42))
    end
    summary()
end

--------------------------------------------------------------------------------
-- Switching

local function enable()
    session = session + 1
    B.enabled = true
    pending = false
    API.RegisterEvents(events, B.EVENTS)
    states = {}
    B.Refresh(true)
    startTicker()
end

local function disable()
    session = session + 1
    B.enabled = false
    pending = false
    events:UnregisterAllEvents()
    bankOpen = false
    stopTicker()
    clear()
    states = {}
    clearTarget()
    if GP.BooksFrame then GP.BooksFrame.Hide() end
end

GP.Pearls.Register({
    key = B.KEY,
    name = "Library books",
    desc = "WoW Forever's library books you still need on the world map and minimap, and a note when you come near one.",
    help = "A book icon at each place a library book you still need can be found, on the world map (zone and "
        .. "continent) and the minimap. Hover one for the book and where it is. Books you carry, keep in your bank "
        .. "or have handed in aren't shown. Within 100 yards of a book you still need, a note appears (it stays "
        .. "until you click it) and a line in chat; it comes again only after you've gone 150 yards away. "
        .. "A compass under your character then points at that book until you reach it, go 150 yards away, or "
        .. "no longer need it (Alt-drag it to move it; /gpearls books compass reset puts it back). "
        .. "No notes in instances, while dead or on a flight.",
    default = true,
    category = "Interface",
    section = "Maps",
    defaults = { worldmap = true, minimap = true, nearby = true, compass = true },
    Enable = enable,
    Disable = disable,
    onSettingChanged = function(name)
        if not B.enabled then return end
        if name == "nearby" then
            if setting("nearby") then startTicker() else stopTicker(); clearTarget() end
        elseif name == "compass" then
            if not setting("compass") then clearTarget() end
        else
            B.Build()
        end
    end,
    configure = function(panel, refreshers)
        if GP.BooksFrame then GP.BooksFrame.Configure(panel, refreshers) end
    end,
    commands = { books = { help = "[test or compass reset] - library books still to find and the nearest, a test "
                               .. "note, or the compass back under your character",
                           run = command } },
})

B._test = {
    events = events, frames = frames, used = used, states = function() return states end,
    latched = latched, ticker = function() return ticker end, recordBank = recordBank, store = store,
    setTarget = function(b) target = b end,
    bankOpen = function() return bankOpen end,
}
